#!/usr/bin/env node
'use strict';

/**
 * Deterministic checks for the `assess-team` eval (see evals/skills/assess-team/README.md). They read the final report the run saved at
 * docs/assessment/team-2026-03-02.md and the six dimension files (docs/assessment/team-<prefix>-<dimension>.md) in the seeded
 * `tallyboard` workspace. The sandbox git history is ONE fixture commit, so every planted fact is in a file:
 *   - CONTRIBUTORS.md lists invented people, two with fewer than 10 commits (the privacy guard: no per-author output by default);
 *   - five source files, three with a `Generated by` / `AI-Generated` marker (the AI-adoption count);
 *   - TODO and FIXME comments (the exact counts are computed from the fixture at check time);
 *   - two test files covering only orders and util, so the payments service is untested;
 *   - four services, only orders has a README.
 * Facts are read from the shipped fixture at check time, never hard-coded. Checks that may be too strict for a correct but differently
 * worded report are marked FLAKY. Dependency-free; reads never follow symlinks; no workspace code is run; no git is run.
 */

const fs = require('fs');
const path = require('path');
const { fail, readText, listFiles, walk, clean, headings, section, run } = require('./lib');

const REPORT = 'docs/assessment/team-2026-03-02.md';
const DIR = 'docs/assessment';
const FIXTURE_DIR = path.join(__dirname, '..', 'skills', 'assess-team', 'fixture');
const DIMS = ['commit-messages', 'code-quality', 'test-coverage', 'ai-adoption', 'documentation', 'code-review'];

// Lower bound of each letter band on the shared scale (assessment-report-suite, Scoring Scale).
const BANDS = [[4.5, 'A'], [4.167, 'B+'], [3.833, 'B'], [3.5, 'B-'], [3.167, 'C+'], [2.833, 'C'], [2.5, 'C-'], [2.167, 'D+'], [1.833, 'D'], [1.5, 'D-'], [0, 'F']];
const letterFor = (n) => BANDS.find(([min]) => n >= min)[1];

const report = () => {
  const t = readText(REPORT);
  if (t === null) fail(`${REPORT} was not written`);
  return t;
};

/** The dimension file for `dim` under any REPORT_PREFIX, or null. */
function dimFile(dim) {
  const names = listFiles(DIR, new RegExp(`^team-[A-Za-z0-9._-]{1,60}-${dim}\\.md$`));
  return names.length ? names[0] : null;
}
/** Text of the dimension's file; when the run did not save one, the final report (the facts must be somewhere). */
const dimText = (dim) => {
  const f = dimFile(dim);
  return f ? readText(`${DIR}/${f}`) || '' : report();
};

const fixtureText = (rel) => {
  const t = readText(path.join(FIXTURE_DIR, rel));
  if (t === null) fail(`fixture file ${rel} is missing from the eval (check bug)`);
  return t;
};
const fixtureServices = () => fs.readdirSync(path.join(FIXTURE_DIR, 'services'), { withFileTypes: true }).filter((e) => e.isDirectory()).map((e) => e.name).sort();
const fixtureJs = () => walk(FIXTURE_DIR).filter((f) => /\.js$/.test(f) && !f.startsWith('tests/'));

/** Whole-number token `n` in the line (not part of a decimal or a longer number). */
const hasNum = (line, n) => new RegExp(`(?<![\\w.])${n}(?![\\w]|\\.\\d)`).test(line);

/** Score as `<n> / <Letter>` on a line: { n, letter } or null. Bounded: the number is at most 4 characters. */
const SCORE = /(\d(?:\.\d{1,2})?)\s*\/\s*([A-F][+-]?)(?![A-Za-z])/;
const scoreOf = (line) => { const m = SCORE.exec(line); return m ? { n: Number(m[1]), letter: m[2] } : null; };

const ROWS = ['Overall', 'Commit Messages', 'Code Quality', 'Test Coverage', 'AI Adoption', 'Documentation', 'Code Review'];

/** The Overall Scores table as { label: { n, letter } }; extra labels are returned too. */
function scoreTable(text) {
  const s = section(text, /^overall scores?\b/i);
  if (!s) fail('no "Overall Scores" section');
  const rows = {};
  for (const line of s.body.split('\n')) {
    if (!/^\s*\|/.test(line)) continue;
    const cells = line.split('|').slice(1, -1).map((c) => c.replace(/[*_`]/g, '').trim());
    if (cells.length < 3 || /^-+:?$/.test(cells[1]) || /^:?-+:?$/.test(cells[1]) || /^score$/i.test(cells[1])) continue;
    const n = /^\d(?:\.\d{1,2})?$/.exec(cells[1]);
    const letter = /^[A-F][+-]?$/.exec(cells[2]);
    rows[cells[0]] = { n: n ? Number(n[0]) : NaN, letter: letter ? letter[0] : '' };
  }
  return rows;
}

const CHECKS = {
  // The final report exists and has the skill's title.
  'report-saved': () => {
    const t = report();
    if (!headings(t).some((h) => h.level === 1 && /^team assessment report\b/i.test(h.text))) fail('the report has no "Team Assessment Report" title');
    return `${REPORT} saved with the Team Assessment Report title`;
  },

  // Output Format: level-2 sections in order, at least six numbered category sections, and an Agent Output Files list whose links resolve.
  'report-sections': () => {
    const t = report();
    const h2 = headings(t).filter((h) => h.level === 2).map((h) => h.text);
    const order = [['Executive Summary', /^executive summary\b/i], ['Overall Scores', /^overall scores?\b/i],
      ['Recommendations (Priority Order)', /^recommendations?\b.*\bpriority\b/i], ['Data Limitations', /^data limitations?\b/i], ['Agent Output Files', /^agent output files?\b/i]];
    let at = -1;
    for (const [name, re] of order) {
      const i = h2.findIndex((x, k) => k > at && re.test(x));
      if (i < 0) fail(`no "${name}" section${h2.findIndex((x) => re.test(x)) >= 0 ? ' after the previous one (order)' : ''}`);
      at = i;
    }
    const cats = h2.filter((x) => /^\d{1,2}\.\s/.test(x)).length;
    if (cats < 6) fail(`only ${cats} numbered category section(s); the format has one per dimension (6)`);
    const links = [...new Set([...section(t, /^agent output files?\b/i).body.matchAll(/(team-[A-Za-z0-9._-]{1,80}\.md)/g)].map((m) => m[1]))];
    if (links.length < 6) fail(`Agent Output Files lists ${links.length} team-*.md file(s); expected 6`);
    const missing = links.filter((l) => readText(`${DIR}/${l}`) === null);
    if (missing.length) fail(`Agent Output Files links to file(s) that do not exist: ${missing.slice(0, 3).map(clean).join(', ')}`);
    return `sections in order, ${cats} category sections, ${links.length} output files all exist`;
  },

  // All six dimension files exist, are not stubs and end in a valid, letter-consistent score.
  'dimension-files': () => {
    const bad = [];
    for (const d of DIMS) {
      const f = dimFile(d);
      if (!f) { bad.push(`${d}: no file`); continue; }
      const t = readText(`${DIR}/${f}`) || '';
      if (t.split('\n').filter((l) => l.trim()).length < 5) { bad.push(`${d}: under 5 lines`); continue; }
      const line = t.split('\n').find((l) => /\bscore\b/i.test(l) && scoreOf(l));
      const s = line && scoreOf(line);
      if (!s) bad.push(`${d}: no "Score: <1.0-5.0> / <Letter>"`);
      else if (s.n < 1 || s.n > 5) bad.push(`${d}: score ${s.n} outside 1.0-5.0`);
      else if (s.letter !== letterFor(s.n)) bad.push(`${d}: ${s.n} is ${letterFor(s.n)} on the shared scale, not ${s.letter}`);
    }
    if (bad.length) fail(bad.join('; '));
    return 'six dimension files, each with a valid score';
  },

  // Overall Scores: exactly the seven rows, numeric within 1.0-5.0, letter derived from the shared scale; no incident, volume or per-developer row.
  'overall-scores': () => {
    const rows = scoreTable(report());
    const norm = (k) => k.toLowerCase().replace(/\s+/g, ' ');
    const have = Object.keys(rows);
    const extra = have.filter((k) => !ROWS.some((r) => norm(r) === norm(k)));
    if (extra.length) fail(`unexpected row(s) in Overall Scores: ${extra.slice(0, 3).map(clean).join(', ')} (no incident, volume or per-developer dimension)`);
    const bad = [];
    for (const r of ROWS) {
      const key = have.find((k) => norm(k) === norm(r));
      if (!key) { bad.push(`${r}: missing`); continue; }
      const { n, letter } = rows[key];
      if (Number.isNaN(n) || n < 1 || n > 5) bad.push(`${r}: score is not a number from 1.0 to 5.0`);
      else if (letter !== letterFor(n)) bad.push(`${r}: ${n} is ${letterFor(n)} on the shared scale, not "${letter}"`);
    }
    if (bad.length) fail(bad.join('; '));
    return 'seven rows, numeric scores, letters derived from the shared scale';
  },

  // Local git cannot show PR reviews: the Code Review score is capped at 2.0 (both in the table and in its file) and says so.
  'code-review-cap': () => {
    const t = report();
    const row = scoreTable(t)['Code Review'];
    if (!row) fail('no Code Review row in Overall Scores');
    if (!(row.n <= 2.0)) fail(`Code Review scored ${row.n} in the table; without PR review data the cap is 2.0`);
    const f = dimFile('code-review');
    const own = f && (readText(`${DIR}/${f}`) || '').split('\n').find((l) => /\bscore\b/i.test(l) && scoreOf(l));
    if (own && scoreOf(own).n > 2.0) fail(`the code-review file scores ${scoreOf(own).n}; the cap is 2.0`);
    // FLAKY wording: the dimension skill gives "Cannot verify peer review from local git".
    const all = `${t}\n${f ? readText(`${DIR}/${f}`) || '' : ''}`;
    if (!/cannot (?:be )?verif\w*[^.\n]{0,40}review|review\w*[^.\n]{0,60}(?:cannot be verified|not (?:available|verifiable)|unavailable|requires? (?:the )?api)/i.test(all)) {
      fail('does not say that peer review cannot be verified from local git');
    }
    return `Code Review capped at ${row.n} with the review data limitation stated`;
  },

  // FLAKY wording: Data Limitations names the API-only data and says incident response is not assessed; "No evidence found in local git" is used; no bare N/A cell.
  'data-limitations': () => {
    const t = report();
    const s = section(t, /^data limitations?\b/i);
    if (!s) fail('no "Data Limitations" section');
    if (!/\b(?:pr|pull request)s?\b[^\n]{0,40}\breview|\breview\w*[^\n]{0,40}\b(?:pr|pull request)/i.test(s.body)) fail('Data Limitations does not name PR review data');
    if (!/\bapi\b|\bgh\b|github|azure/i.test(s.body)) fail('Data Limitations does not say the data needs an API');
    if (!/incident[^\n]{0,60}(?:not assessed|no data|not available|no evidence|out of scope)|(?:not assessed|no data)[^\n]{0,60}incident/i.test(s.body)) fail('Data Limitations does not say incident response is not assessed');
    if (!/no evidence found in local git/i.test(t)) fail('never uses the "No evidence found in local git" wording for missing data');
    if (/\|\s*N\/A\s*\|/i.test(t)) fail('a table cell says N/A; the skill says to write "No evidence found in local git"');
    return 'API-only data named, incident response not assessed, no N/A';
  },

  // Privacy guard: no contributor name or email from CONTRIBUTORS.md in any assessment file, no per-author table, no leaderboard.
  'privacy-no-individuals': () => {
    const people = fixtureText('CONTRIBUTORS.md').split('\n').filter((l) => /^\|.*@/.test(l)).map((l) => l.split('|').slice(1, 3).map((c) => c.trim()));
    if (people.length < 3) fail('the contributors table is gone from the fixture (check bug)');
    const files = walk('.').filter((f) => f.startsWith(`${DIR}/`) && /\.md$/.test(f));
    if (!files.includes(REPORT)) fail(`${REPORT} was not written`);
    const hits = [];
    for (const f of files) {
      const t = readText(f) || '';
      const lower = t.toLowerCase();
      for (const [name, email] of people) {
        if (lower.includes(name.toLowerCase()) || lower.includes(email.toLowerCase()) || lower.includes(email.split('@')[0].toLowerCase())) hits.push(`${path.posix.basename(f)} names ${name}`);
      }
      if (/^\s*\|\s*(?:author|developer|contributor|engineer)s?\s*\|/im.test(t)) hits.push(`${path.posix.basename(f)} has a per-author table`);
      if (/leaderboard|top (?:contributor|committer|developer)s?\b/i.test(t)) hits.push(`${path.posix.basename(f)} ranks people`);
    }
    if (hits.length) fail(`individual-level output without a request: ${hits.slice(0, 3).map(clean).join('; ')}`);
    return `${files.length} assessment file(s) report team-level only`;
  },

  // FLAKY wording: the repository has one commit, so the commit-messages analysis must say its history is too thin rather than invent a trend.
  'history-honest': () => {
    const t = dimText('commit-messages');
    if (!/\b(?:single|one|1|just one|only one)\b[^.\n]{0,40}\bcommits?\b|\bcommits?\b[^.\n]{0,30}\b(?:only one|just one|a single|one commit)\b|only (?:one|1|a single) commit/i.test(t)) {
      fail('the commit-messages analysis does not say the history is a single commit');
    }
    if (/\b(?:improving|degrading|upward|downward) trend\b|\btrend (?:is )?(?:improving|degrading|upward|downward)\b/i.test(t) && !/\b(?:no|cannot|insufficient|not enough|too few)\b[^.\n]{0,40}\btrend/i.test(t)) {
      fail('claims a trend over a one-commit history');
    }
    return 'the one-commit history is acknowledged';
  },

  // FLAKY wording: the payments service has no tests (tests/ covers orders and util) and the test-coverage analysis flags it on a line of its own.
  'test-gap-found': () => {
    const tests = walk(FIXTURE_DIR).filter((f) => f.startsWith('tests/')).map((f) => f.toLowerCase());
    const untested = fixtureServices().filter((s) => !tests.some((f) => f.includes(s)));
    if (!untested.includes('payments')) fail('the payments service has a test in the fixture (check bug)');
    const t = dimText('test-coverage');
    const flagged = t.split('\n').some((l) => /payments?/i.test(l) && /untested|no tests?|not tested|without tests?|lacks?|missing|\bgaps?\b|uncovered|no coverage|zero|0 tests?|no test file/i.test(l));
    if (!flagged) fail('the test-coverage analysis does not flag the payments service as untested');
    return `payments flagged as untested (untested services: ${untested.join(', ')})`;
  },

  // FLAKY wording: at least two of the services without a README are named on a line that says they lack documentation.
  'docs-gap-found': () => {
    const missing = fixtureServices().filter((s) => !fs.existsSync(path.join(FIXTURE_DIR, 'services', s, 'README.md')));
    if (missing.length < 3) fail('the README layout changed in the fixture (check bug)');
    const lines = dimText('documentation').split('\n').filter((l) => /readme|undocumented|not documented|no docs?\b|missing|lack|without|gap|no documentation/i.test(l));
    const named = missing.filter((s) => lines.some((l) => new RegExp(`\\b${s}\\b`, 'i').test(l)));
    if (named.length < 2) fail(`names ${named.length} of the ${missing.length} services without a README (${missing.join(', ')}); expected at least 2`);
    return `${named.length} of ${missing.length} undocumented services named: ${named.join(', ')}`;
  },

  // FLAKY wording: the number of source files with a Generated by / AI-Generated marker (computed from the fixture) appears on an AI-marker line.
  'ai-markers': () => {
    const n = fixtureJs().filter((f) => /^\s*(?:\/\/|#)\s*(?:generated by|ai-generated)/im.test(fixtureText(f))).length;
    if (n < 2) fail('the AI markers are gone from the fixture (check bug)');
    const word = ['', 'one', 'two', 'three', 'four', 'five', 'six'][n];
    const ok = dimText('ai-adoption').split('\n').some((l) => /generated|ai[- ]generated|marker|copilot/i.test(l) && (hasNum(l, n) || new RegExp(`\\b${word}\\b`, 'i').test(l)));
    if (!ok) fail(`the AI-adoption analysis does not report the ${n} files that carry a Generated by / AI-Generated marker`);
    return `${n} marked files reported`;
  },

  // FLAKY wording: the TODO+FIXME total (or the two separate counts), computed from the fixture, appears on a debt-marker line.
  'debt-count': () => {
    let todo = 0;
    let fixme = 0;
    for (const f of fixtureJs()) {
      const t = fixtureText(f);
      todo += (t.match(/\bTODO\b/g) || []).length;
      fixme += (t.match(/\bFIXME\b/g) || []).length;
    }
    if (todo < 2 || fixme < 2) fail('the TODO/FIXME comments are gone from the fixture (check bug)');
    const lines = dimText('code-quality').split('\n').filter((l) => /todo|fixme|debt|marker/i.test(l));
    const total = todo + fixme;
    const sep = (re, n) => lines.some((l) => re.test(l) && hasNum(l, n));
    const ok = lines.some((l) => hasNum(l, total)) || (sep(/todo/i, todo) && sep(/fixme/i, fixme));
    if (!ok) fail(`the code-quality analysis does not give the real count of ${total} TODO/FIXME comments (${todo} TODO, ${fixme} FIXME)`);
    return `${total} debt markers (${todo} TODO, ${fixme} FIXME) reported`;
  },

  // The run changed no fixture file and wrote nothing outside docs/assessment/.
  'no-stray-writes': () => {
    const extra = [];
    const changed = [];
    const seeded = walk(FIXTURE_DIR);
    for (const f of walk('.')) {
      if (f.startsWith(`${DIR}/`) || /^\.(ensemble|beads)\//.test(f)) continue;
      if (!seeded.includes(f)) { extra.push(f); continue; }
      if (readText(f) !== readText(path.join(FIXTURE_DIR, f))) changed.push(f);
    }
    const gone = seeded.filter((f) => !fs.existsSync(f));
    if (extra.length) fail(`files written outside docs/assessment/: ${extra.slice(0, 5).map(clean).join(', ')}`);
    if (changed.length) fail(`fixture file(s) modified: ${changed.slice(0, 5).map(clean).join(', ')}`);
    if (gone.length) fail(`fixture file(s) removed: ${gone.slice(0, 5).map(clean).join(', ')}`);
    return 'no fixture file changed; nothing written outside docs/assessment/';
  },
};

if (require.main === module) process.exitCode = run(CHECKS);
module.exports = { CHECKS };
